mapper.select:
SELECT TEMP_SEQ, LEGACY_SYSTEM_CD, LEGACY_CUST_ID, CUST_NM, CI_VAL, DI_VAL, BIRTH_DATE, GENDER, NATIONAL_INFO, CELL_NO, RRN_HASH, VALID_STATUS, MIGRATION_STATUS, ERROR_MSG, SOURCE_EXTRACT_DT, REG_DT FROM TB_CI_MIGRATION_TEMP
AND VALID_STATUS = #{validStatus}
AND MIGRATION_STATUS = #{migrationStatus}
ORDER BY TEMP_SEQ ASC

mapper.update:
UPDATE TB_CI_MIGRATION_TEMP
SET
    VALID_STATUS = #{validStatus},
    ERROR_MSG = #{errorMsg}
WHERE TEMP_SEQ = #{tempSeq}

UPDATE TB_CI_MIGRATION_TEMP
SET
    MIGRATION_STATUS = #{migrationStatus}
WHERE TEMP_SEQ = #{tempSeq}

